// Backs the "Pose Tool" dashboard page: given a reference photo (runway,
// lookbook, or any photo of a person in a pose), produces:
//   1. A structured, plain-English breakdown of the pose by body region,
//      written toward CLO3D's Avatar Pose editor — something a designer can
//      use to manually dial in the avatar's pose quickly instead of
//      eyeballing the photo joint-by-joint.
//   2. A 3-angle (front/side/back) turnaround of a neutral mannequin in that
//      same pose, generated by OpenAI's image model, as a visual reference
//      sheet — NOT a real 3D mesh or skeleton (the model can't produce that; it
//      can only read an image and generate new ones), just a faster visual
//      reference than the single source photo.
//
// IMPORTANT HONESTY NOTE: any joint-angle language in the output is the AI's
// visual *estimate*, not measured data. Treat it as a fast starting point for
// posing an avatar by hand, not as literal, precise rotation values.
const archiver = require("archiver");
const { nanoid } = require("nanoid");
const fs = require("fs");
const path = require("path");

// Models are overridable via env. Vision reuses a multimodal chat model; image
// generation needs an image model (gpt-image-2.5-sunburst may require OpenAI org verification).
const POSE_MODEL = process.env.OPENAI_POSE_MODEL || "gpt-4o-mini";
const IMAGE_MODEL = process.env.OPENAI_IMAGE_MODEL || "gpt-image-2.5-sunburst";
const { post, MISSING } = require("./openaiClient");

const POSE_SYSTEM_INSTRUCTION = `You are a fashion/fit specialist helping a CLO3D garment designer quickly pose a 3D avatar to match a reference photo.

Look at the photo of a person/model and describe their pose region by region, in plain language a designer can use to manually adjust CLO3D's Avatar Pose editor (which poses a skeleton with regions like head/neck, spine/torso, shoulders, arms, hands, hips, legs, feet). Where useful, give a rough qualitative angle (e.g. "left arm raised ~45° from torso, elbow bent ~90°") but always make clear these are visual estimates, not precise measurements.

Also write one single short, neutral, purely physical description of the body pose alone — no clothing, no face, no identity, no background — suitable as an image-generation prompt for a plain grey studio mannequin/dress-form in that exact pose. This description must be safe and generic: describe joint positions and stance only.

You MUST reply with ONLY a raw JSON object (no markdown fences, no commentary outside the JSON) in exactly this shape:
{
  "summary": "one or two sentence overview of the pose and its overall mood/energy",
  "stance": "footing/stance description, e.g. weight-bearing leg, foot placement",
  "weightDistribution": "short description of where the weight sits",
  "regions": {
    "headNeck": "...",
    "spineTorso": "...",
    "leftArm": "...",
    "rightArm": "...",
    "leftLeg": "...",
    "rightLeg": "..."
  },
  "clo3dTips": ["short actionable tip", "..."],
  "imagePrompt": "the neutral physical-pose-only description described above"
}`;

function safeParsePoseJson(raw) {
  if (!raw) return null;
  const cleaned = raw.trim().replace(/^```json\s*|^```\s*|```$/g, "").trim();
  try {
    const parsed = JSON.parse(cleaned);
    if (typeof parsed.imagePrompt !== "string") return null;
    return parsed;
  } catch {
    // Fall back to pulling out the first {...} block, in case the model
    // wrapped the JSON in stray commentary despite being told not to.
    const start = cleaned.indexOf("{");
    const end = cleaned.lastIndexOf("}");
    if (start === -1 || end === -1 || end <= start) return null;
    try {
      const parsed = JSON.parse(cleaned.slice(start, end + 1));
      if (typeof parsed.imagePrompt !== "string") return null;
      return parsed;
    } catch {
      return null;
    }
  }
}

/**
 * Sends the uploaded photo to OpenAI and gets back a structured pose
 * breakdown plus a neutral image-generation prompt for the turnaround step.
 *
 * @param {Buffer} imageBuffer
 * @param {string} mimeType e.g. "image/png"
 * @returns {Promise<object>} parsed pose JSON (see POSE_SYSTEM_INSTRUCTION shape)
 */
async function analyzePose(imageBuffer, mimeType) {
  const data = await post("/chat/completions", {
    model: POSE_MODEL,
    messages: [
      { role: "system", content: POSE_SYSTEM_INSTRUCTION },
      { role: "user", content: [
        { type: "image_url", image_url: { url: `data:${mimeType};base64,${imageBuffer.toString("base64")}` } },
        { type: "text", text: "Analyze the pose in this photo." },
      ] },
    ],
    max_tokens: 3072,
    response_format: { type: "json_object" },
  }, 90_000);
  const choice = data?.choices?.[0];
  const raw = choice?.message?.content || "";
  const parsed = safeParsePoseJson(raw);
  if (!parsed) {
    console.error("Pose analysis failed to parse. finish_reason=%s refusal=%s rawLength=%d preview=%s", choice?.finish_reason, choice?.message?.refusal, raw.length, raw.slice(0, 500));
    if (choice?.finish_reason === "length") throw new Error("The AI ran out of output tokens while analyzing the pose. Please try again.");
    if (choice?.message?.refusal || choice?.finish_reason === "content_filter") throw new Error("The AI declined to analyze this photo. Please try a different one.");
    throw new Error("The AI returned an unexpected response while analyzing the pose.");
  }
  return parsed;
}

const ANGLE_PROMPTS = {
  front: "Front view (camera facing the figure directly), full body, head to toe visible.",
  side: "Side/profile view (camera at 90° to the figure), full body, head to toe visible.",
  back: "Back view (camera behind the figure), full body, head to toe visible.",
};

const IMAGE_STYLE_PREFIX =
  "A plain matte-grey featureless studio mannequin / dress-form figure (no face, no clothing, no hair, no skin tone, no identity), standing in the exact body pose described below, on a seamless white studio background, soft even lighting, orthographic-feeling full-body reference shot. ";

/**
 * Generates one turnaround-angle image via OpenAI's image model.
 * Returns { buffer: Buffer|null, warning: string|null }.
 */
async function generateAngleImage(poseImagePrompt, angle) {
  const prompt = `${IMAGE_STYLE_PREFIX}${ANGLE_PROMPTS[angle]} Pose: ${poseImagePrompt}`;
  const isDalle = IMAGE_MODEL.startsWith("dall-e");
  const body = isDalle
    ? { model: IMAGE_MODEL, prompt, n: 1, size: "1024x1792", response_format: "b64_json" }
    : { model: IMAGE_MODEL, prompt, n: 1, size: "1024x1536", quality: process.env.OPENAI_IMAGE_QUALITY || "medium" };
  const data = await post("/images/generations", body, 120_000);
  const b64 = data?.data?.[0]?.b64_json;
  if (!b64) {
    console.error(`Pose turnaround (${angle}): no image returned.`, JSON.stringify(data).slice(0, 300));
    return { buffer: null, warning: `The ${angle} view wasn't generated.` };
  }
  return { buffer: Buffer.from(b64, "base64"), warning: null };
}

/**
 * Generates all three turnaround angles. Best-effort per-angle: if one
 * angle fails, the others are still returned rather than failing the whole
 * request (mirrors the garment tool's "never fail the whole thing over an
 * optional extra" approach).
 *
 * @returns {Promise<{images: {front,side,back}, warnings: {front,side,back}}>}
 *   images values are Buffer|null, warnings values are string|null.
 */
async function generateTurnaroundImages(poseImagePrompt) {
  const angles = ["front", "side", "back"];
  const results = await Promise.all(
    angles.map(async (angle) => {
      try {
        const { buffer, warning } = await generateAngleImage(poseImagePrompt, angle);
        return [angle, { buffer, warning }];
      } catch (err) {
        console.error(`Pose turnaround (${angle}) generation failed:`, err.message);
        return [angle, { buffer: null, warning: `The ${angle} view failed to generate: ${err.message}` }];
      }
    })
  );

  const images = {};
  const warnings = {};
  for (const [angle, { buffer, warning }] of results) {
    images[angle] = buffer;
    warnings[angle] = warning;
  }
  return { images, warnings };
}

function poseNotesText(pose) {
  const lines = [
    "POSE REFERENCE NOTES (AI-generated visual estimate — treat angles as a starting point, not precise measurements)",
    "",
    `Summary: ${pose.summary || "-"}`,
    `Stance: ${pose.stance || "-"}`,
    `Weight distribution: ${pose.weightDistribution || "-"}`,
    "",
    "By region (for CLO3D's Avatar Pose editor):",
    `  Head / neck: ${pose.regions?.headNeck || "-"}`,
    `  Spine / torso: ${pose.regions?.spineTorso || "-"}`,
    `  Left arm: ${pose.regions?.leftArm || "-"}`,
    `  Right arm: ${pose.regions?.rightArm || "-"}`,
    `  Left leg: ${pose.regions?.leftLeg || "-"}`,
    `  Right leg: ${pose.regions?.rightLeg || "-"}`,
    "",
    "CLO3D tips:",
    ...(pose.clo3dTips || []).map((t) => `  - ${t}`),
  ];
  return lines.join("\n");
}

/**
 * Bundles the pose notes (JSON + readable text) and any generated
 * turnaround images into a single .zip, the same archiver-based pattern as
 * lib/garmentTool.js's buildGarmentZip.
 */
async function buildPoseZip({ pose, images }, destDir) {
  fs.mkdirSync(destDir, { recursive: true });
  const filename = `${nanoid(14)}-pose.zip`;
  const filePath = path.join(destDir, filename);

  await new Promise((resolve, reject) => {
    const output = fs.createWriteStream(filePath);
    const archive = archiver("zip", { zlib: { level: 9 } });

    output.on("close", resolve);
    archive.on("error", reject);
    archive.pipe(output);

    archive.append(JSON.stringify(pose, null, 2), { name: "pose-notes.json" });
    archive.append(poseNotesText(pose), { name: "pose-notes.txt" });

    for (const angle of ["front", "side", "back"]) {
      if (images[angle]) {
        archive.append(images[angle], { name: `reference/${angle}.png` });
      }
    }

    archive.finalize();
  });

  return filePath;
}

module.exports = {
  analyzePose,
  generateTurnaroundImages,
  buildPoseZip,
  poseNotesText,
};
